# Search for Highway trust fund receipt/outlay data by year in the JSON
import json

with open("/app/resources/treasury_bulletin_1992_03.json") as f:
    data = json.load(f)

def search(obj, target):
    results = []
    if isinstance(obj, dict):
        for k, v in obj.items():
            if target.lower() in str(k).lower() or target.lower() in str(v).lower():
                results.append((k, str(v)[:300]))
        for v in obj.values():
            results.extend(search(v, target))
    elif isinstance(obj, list):
        for item in obj:
            results.extend(search(item, target))
    return results

# Search for highway trust fund data
results = search(data, "Highway trust fund")
for r in results[:20]:
    print(r)
    print("---")
