# Let's try to find any chart/image data in the JSON for page 158
import json

with open("/app/resources/treasury_bulletin_1992_03.json") as f:
    data = json.load(f)

# Look for figure elements
def find_figures(obj, path=""):
    results = []
    if isinstance(obj, dict):
        if obj.get('type') == 'figure':
            results.append((path, obj.get('description'), str(obj.get('content',''))[:200]))
        for k, v in obj.items():
            results.extend(find_figures(v, f"{path}.{k}"))
    elif isinstance(obj, list):
        for i, item in enumerate(obj):
            results.extend(find_figures(item, f"{path}[{i}]"))
    return results

figs = find_figures(data, "root")
for f in figs:
    print(f)
    print("---")
